// Backgroud principal image
import background from "../assets/images/background.svg";

// Icon generics
import iconBack from "../assets/images/iconBack.svg";
import iconoOpen from "../assets/images/iconoOpen.png";
import logo from "../assets/images/logo.svg";
import iconSound from "../assets/images/iconSound.svg";
import iconSoundWhite from "../assets/images/iconoNotaBlanco.svg";
import cancelIcon from "../assets/images/wrong.svg";
import checkIcon from "../assets/images/check.svg";
import iconClose from "../assets/images/iconClose.svg";
import imageClose from "../assets/images/closeIcon.png";
import iconOpenModule from "../assets/images/IconoModulosVolve.svg";
import iconCloseModule from "../assets/images/IconoModulosVolver.svg";
import menuMovil from "../assets/images/menuMovil.svg";
import correo from "../assets/images/correo.svg";
import bien from "../assets/images/bien.svg";

// Icons Home

import caraDino from "../assets/images/caraDino.svg";
import caraHipo from "../assets/images/caraHipo.svg";
import caraKoala from "../assets/images/caraKoala.svg";
import caraOso from "../assets/images/caraOso.svg";
import caraPato from "../assets/images/caraPato.svg";
import caravaca from "../assets/images/caravaca.svg";
import iconoArmar from "../assets/images/iconoArmar.svg";
import iconoOtono from "../assets/images/iconoOtono.svg";
import iconoColorear from "../assets/images/iconoColorear.svg";
import iconoEscritura from "../assets/images/iconoEscritura.svg";
import iconoEscucha from "../assets/images/iconoEscucha.svg";
import iconopares from "../assets/images/iconopares.svg";
import iconoVocabulario from "../assets/images/iconoVocabulario.svg";

// background module 6

import greenLeaf from "../assets/images/hojaPrincialVerde.svg";
import wrongLeaf from "../assets/images/hojaRespuestaNegativa.svg";
import goodLeaf from "../assets/images/hojaRespuestaVerdadera.svg";
import letterLeaf from "../assets/images/hojaVocale.svg";

// Exporting resources shared
export {
  iconBack,
  iconoOpen,
  logo,
  background,
  iconSound,
  cancelIcon,
  checkIcon,
  iconClose,
  iconSoundWhite,
  caraDino,
  caraHipo,
  caraKoala,
  caraOso,
  caraPato,
  caravaca,
  iconoArmar,
  iconoOtono,
  iconoColorear,
  iconoEscritura,
  iconoEscucha,
  iconopares,
  iconoVocabulario,
  greenLeaf,
  wrongLeaf,
  goodLeaf,
  letterLeaf,
  imageClose,
  iconOpenModule,
  iconCloseModule,
  menuMovil,
  correo,
  bien,
};
